import{_ as a,C as s,o as n,c as d,aj as e,E as o}from"./framework.js";const b=JSON.parse('{"title":"设置 | Cms / Commerce | Documentation","description":"站点级 电商全局配置（Commerce Store settings）：计量单位、结账可用支付方式、商品/分类/订单的字段模型，以及规格与数字商品的显示规则。保存后影响 商品类型、商品管理、商品分类、订单 等模块；脚本侧通过 k.commerce.settings 读取，见 k.commerce 设置。","frontmatter":{"title":"设置 | Cms / Commerce | Documentation","description":"站点级 电商全局配置（Commerce Store settings）：计量单位、结账可用支付方式、商品/分类/订单的字段模型，以及规格与数字商品的显示规则。保存后影响 商品类型、商品管理、商品分类、订单 等模块；脚本侧通过 k.commerce.settings 读取，见 k.commerce 设置。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/commerce/settings.html"}]]},"headers":[],"relativePath":"zh/cms/commerce/settings.md","filePath":"cms/commerce/settings.md","lastUpdated":1780977342000}'),c={name:"zh/cms/commerce/settings.md"};function m(h,t,i,l,g,p){const r=s("DocImage");return n(),d("div",null,[t[0]||(t[0]=e('<h1 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h1><blockquote><p>菜单：<strong>电商 → 设置</strong><br> 深链：<code>/_Admin/commerce/settings?SiteId={站点GUID}</code></p></blockquote><p>站点级 <strong>电商全局配置</strong>（Commerce Store <code>settings</code>）：计量单位、结账可用支付方式、商品/分类/订单的字段模型，以及规格与数字商品的显示规则。保存后影响 <a href="./product-types.html">商品类型</a>、<a href="./product-management.html">商品管理</a>、<a href="./product-categories.html">商品分类</a>、<a href="./orders.html">订单</a> 等模块；脚本侧通过 <code>k.commerce.settings</code> 读取，见 <a href="/kb-docs/zh/api/commerce/settings.html">k.commerce 设置</a>。</p><div class="tip custom-block"><p class="custom-block-title">与「货币」菜单</p><p>前台默认 <strong>货币代码 / 符号</strong> 多在 <strong>电商 → 货币</strong> 单独维护；本页首屏 <strong>基础</strong> 区当前为 <strong>重量单位</strong> 与 <strong>支付方式</strong>（若后续界面开放货币下拉，以实际后台为准）。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选 <strong>电商 → 设置</strong>（及父级 <strong>电商</strong>）。</li><li>左侧 <strong>电商 → 设置</strong>。</li></ol><h2 id="页面结构" tabindex="-1">页面结构 <a class="header-anchor" href="#页面结构" aria-label="Permalink to &quot;页面结构&quot;">​</a></h2><p>单页表单，自上而下三块白底卡片 + 底部固定 <strong>保存</strong>（<code>KBottomBar</code>，无 <strong>取消</strong>）。支持快捷键保存（与站点其它编辑页一致）。</p>',8)),o(r,{src:"/cms/commerce/commerce-settings-overview.png",alt:"电商设置：基础、自定义字段、显示开关三块区域",width:"1120"}),t[1]||(t[1]=e('<table tabindex="0"><thead><tr><th>区块</th><th>内容</th></tr></thead><tbody><tr><td><strong>基础</strong></td><td>重量单位、启用的支付方式</td></tr><tr><td><strong>自定义字段</strong></td><td>商品字段、分类字段、订单扩展字段</td></tr><tr><td><strong>显示开关</strong></td><td>隐藏属性 / 隐藏规格 / 数字商品交付项必填（条件显示）</td></tr></tbody></table><h2 id="基础" tabindex="-1">基础 <a class="header-anchor" href="#基础" aria-label="Permalink to &quot;基础&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td><strong>重量单位</strong></td><td><code>kg</code> 或 <code>g</code>；用于商品变体重量及 <a href="./shippings.html">配送</a> 等运费相关计算</td></tr><tr><td><strong>启用的支付方式</strong></td><td>多选下拉；选项来自站点已安装的支付模块（须先在 <a href="/kb-docs/zh/cms/navigation.html">服务集成</a> <code>/_Admin/system/config</code> 配置支付能力，见 <a href="/kb-docs/zh/api/payment/">k.payment</a>）。保存为 <code>payments</code> 数组，结账仅展示已启用项。Tooltip：为 <code>k.commerce.settings.payments</code> 配置</td></tr></tbody></table><h2 id="自定义字段" tabindex="-1">自定义字段 <a class="header-anchor" href="#自定义字段" aria-label="Permalink to &quot;自定义字段&quot;">​</a></h2><p>三个 <strong>SortableList</strong> 列表，结构类似 <a href="./../content/content-types.html">内容 → 数据类型</a> 的字段表，但数据写入电商 <code>settings</code> 而非内容类型。</p>',5)),o(r,{src:"/cms/commerce/commerce-settings-custom-fields.png",alt:"电商设置：商品字段、分类字段、订单扩展字段列表",width:"1120"}),t[2]||(t[2]=e('<h3 id="商品字段" tabindex="-1">商品字段 <a class="header-anchor" href="#商品字段" aria-label="Permalink to &quot;商品字段&quot;">​</a></h3><p>控制 <a href="./product-management-detail.html">商品详情</a> 表单与 <a href="./product-management.html">商品管理</a> 列表 <strong>摘要列</strong>。</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>添加</strong></td><td>打开 <strong>自定义字段</strong> 弹窗，配置新字段</td></tr><tr><td><strong>编辑</strong></td><td>修改类型、显示名、验证、是否摘要列等</td></tr><tr><td><strong>删除</strong></td><td>非 <strong>系统字段</strong> 可删；系统字段（如 Title、Images）不可删除</td></tr><tr><td><strong>排序</strong></td><td>拖拽调整字段顺序</td></tr></tbody></table><p>Tooltip：<strong>摘要字段将显示在列表页面上</strong>。</p><h3 id="分类字段" tabindex="-1">分类字段 <a class="header-anchor" href="#分类字段" aria-label="Permalink to &quot;分类字段&quot;">​</a></h3><p>控制 <a href="./product-categories.html">商品分类</a> 编辑页与列表动态列，规则同商品字段。</p><h3 id="订单扩展字段" tabindex="-1">订单扩展字段 <a class="header-anchor" href="#订单扩展字段" aria-label="Permalink to &quot;订单扩展字段&quot;">​</a></h3><p>为 <a href="./orders.html">订单</a> 增加扩展数据定义；字段类型偏订单场景（如是否可筛选 <code>filterable</code>、是否可导出 <code>exportable</code>、列宽等），与商品自定义字段弹窗略有不同。</p><h3 id="自定义字段弹窗-商品-分类" tabindex="-1">自定义字段弹窗（商品 / 分类） <a class="header-anchor" href="#自定义字段弹窗-商品-分类" aria-label="Permalink to &quot;自定义字段弹窗（商品 / 分类）&quot;">​</a></h3><p>点击商品或分类字段列表的 <strong>添加</strong> 或行内 <strong>编辑</strong> 打开 <code>CustomFieldDialog</code>。</p>',10)),o(r,{src:"/cms/commerce/commerce-settings-custom-field-dialog.png",alt:"自定义字段弹窗：基础、高级、验证等 Tab",width:"960"}),t[3]||(t[3]=e('<p>常见配置（与内容字段编辑器同类控件）：</p><table tabindex="0"><thead><tr><th>Tab / 项</th><th>说明</th></tr></thead><tbody><tr><td><strong>基础</strong></td><td>名称、显示名、控件类型（文本、富文本、图片、选择等）、是否多值、是否 <strong>摘要字段</strong>、是否多语言等</td></tr><tr><td><strong>高级</strong></td><td>动态选项、关联内容夹等（视控件类型显示）</td></tr><tr><td><strong>验证</strong></td><td>必填、长度等规则</td></tr><tr><td>系统字段 <strong>Images / Image</strong></td><td>允许编辑图片 <strong>meta</strong> 模板（商品主图/分类图元数据）</td></tr></tbody></table><p>保存弹窗后字段进入对应列表；须再点页面底部 <strong>保存</strong> 才写入站点。</p><h2 id="显示开关" tabindex="-1">显示开关 <a class="header-anchor" href="#显示开关" aria-label="Permalink to &quot;显示开关&quot;">​</a></h2>',4)),o(r,{src:"/cms/commerce/commerce-settings-display.png",alt:"电商设置：隐藏属性、隐藏规格、数字商品交付项必填",width:"1120"}),t[4]||(t[4]=e('<table tabindex="0"><thead><tr><th>开关</th><th>说明</th></tr></thead><tbody><tr><td><strong>隐藏属性</strong></td><td>开启后，<a href="./product-types.html">商品类型</a> 创建弹窗与列表 <strong>属性</strong> 列隐藏；<a href="./product-management-detail.html">商品详情</a> 基本信息区不显示 <strong>属性</strong> 键值对</td></tr><tr><td><strong>隐藏规格</strong></td><td>开启后，商品按单规格处理；类型与详情无 <strong>规格选项 / 变体</strong> 区块，列表不显示规格数</td></tr><tr><td><strong>产品数字内容不能为空</strong></td><td>仅当存在 <strong>至少一种</strong> 勾选了 <strong>数字商品</strong> 的 <a href="./product-types.html">商品类型</a> 时显示；开启后，保存数字商品时每个变体须配置 <a href="./product-management-detail.html#数字商品">数字产品</a> 交付项</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./">电商概述</a> — 建议实施顺序</li><li><a href="./product-types.html">商品类型</a> · <a href="./product-management.html">商品管理</a> · <a href="./product-categories.html">商品分类</a></li><li><a href="./currencies.html">货币</a> · <a href="./shippings.html">配送</a> · <a href="./discounts.html">优惠折扣</a></li><li><a href="/kb-docs/zh/api/commerce/settings.html">k.commerce 设置</a></li></ul>',3))])}const u=a(c,[["render",m]]);export{b as __pageData,u as default};
